'use strict';

function exercise(id, topic, source, stem, options, answer, explanation) {
  return { id, topic, source, stem, options, answer, explanation, origin: 'new' };
}

function discursive(id, topic, source, stem, explanation) {
  return { id, topic, source, stem, options: [], answer: null, explanation, origin: 'new', discursive: true };
}

function historical(id, topic, source, page, stem, options, answer, explanation) {
  return { id, topic, source, page, stem, options, answer, explanation, origin: 'historical' };
}

